expanded_tips = []
for i in range(106):
    base = detailed_tips[i % len(detailed_tips)]
    title = base[0]
    if i >= len(detailed_tips):
        modifier = ["(Part 2)", "(Advanced)", "(Night Time)", "(Urban)", "(Rural)", "(School)", "(Workplace)"]
        title = base[0] + " " + modifier[(i // len(detailed_tips)) % len(modifier)]
    expanded_tips.append((title, base[1], base[2]))

pack_str = "      final pack = [\n"
for t in expanded_tips:
    content = t[1].replace("'", "\\'")
    pack_str += f"        ('{t[0]}', '{content}', '{t[2]}'),\n"
pack_str += "      ];"

code = re.sub(r'final pack = \[\s*\(.*?\s*\];', pack_str, code, flags=re.DOTALL)

with open(path, 'w', encoding='utf-8') as f:
    f.write(code)
